    "category": "config_regression",
    "service": "orders",
    "summary": "orders service had its inventory call timeout reduced from 800ms to 8ms, causing widespread timeouts"
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "ops config change set orders timeout.inventory_ms to 8ms (from 800ms)",
      "status": "confirmed",
      "cites": ["ops-E0001"]
    },
    {
      "claim": "after the change, orders service began logging upstream_timeout errors when calling inventory with timeout_ms:8",
      "status": "confirmed",
      "cites": ["orders-L00030"]
    },
    {
      "claim": "orders service returned HTTP 504 errors to its caller (gateway) due to these timeouts",
      "status": "confirmed",
      "cites": ["gateway-L0002d"]
    },
    {
      "claim": "gateway began returning 504 errors to users, visible as increased err5xx and latency in gateway metrics",
      "status": "confirmed",
      "cites": ["gateway-M000a"]
    }
  ],
  "alternatives": [
    {
      "category": "dependency_slow",
      "service": "inventory",
      "why_less_likely": "inventory latency metrics remain low (p50 ~11ms, p99 ~24-31ms) throughout the incident, indicating no slowdown",
      "cites": ["inventory-M0008"]
    },
    {
      "category": "process_crash",
      "service": "orders",
      "why_less_likely": "orders process did not crash or restart; boots=1 in metrics throughout and no fatal logs",
      "cites": ["orders-M000a"]
    }
  ]
